Rules.InvariantScript:
ClearCollect(
    Menu,
    [
        {Name: "Log in"},
        {Name: "Register"},
        {Name: "Forgot Password"}
    ]
);
Set(
    gblShowErrorImage,
    false
);
Set(
    gblShowLoginErrorIcon,
    false
);
Clear(colCheckCapitalLetters);
Clear(colCheckNumbers);
Clear(colCheckSmallLetters);
Clear(colCheckSymbol);
Set(
    locPasswordError,
    false
);
Set(
    gblBlankEntry,
    false
);

Switch(
    ThisItem.Name,
    "Log in",
    UpdateContext({locPasswordError: false});
    Set(
        gblBlankEntry,
        false
    ),
    "Register",
    UpdateContext({locUsernameError: false});
    UpdateContext({locPasswordError: false});

)
/*
UpdateContext({locPasswordError: false});
    Set(
        gblBlankEntry,
        false
    )
UpdateContext({locUsernameError: false});
UpdateContext({locPasswordError: false});
*/

If(
    Len(txtConfirmPassword.Text) < 14 And (CountRows(
        Filter(
            colCheckNumbers,
            Value
        )
    ) = 0 || CountRows(
        Filter(
            colCheckCapitalLetters,
            Value
        )
    ) = 0 || CountRows(
        Filter(
            colCheckSmallLetters,
            Value
        )
    ) = 0 || CountRows(
        Filter(
            colCheckSymbol,
            Value
        )
    ) = 0),
    DisplayMode.Disabled,
    DisplayMode.Edit
)

// Vérifie si tous les champs obligatoires sont remplis
Set(
    gblBlankEntry,
    IsBlank(txtFullName.Text) || IsBlank(txtUsername.Text) || IsBlank(txtPassword.Text) || IsBlank(txtEmailAddress.Text)
);

// Vérifie s’il y a des chiffres
ClearCollect(
    colCheckNumbers,
    ForAll(
        Split(txtConfirmPassword.Text, ""),
        If(IsMatch(Value, "[0-9]"), Value)
    )
);

// Vérifie s’il y a des majuscules
ClearCollect(
    colCheckCapitalLetters,
    ForAll(
        Split(txtConfirmPassword.Text, ""),
        If(IsMatch(Value, "[A-Z]"), Value)
    )
);

// Vérifie s’il y a des minuscules
ClearCollect(
    colCheckSmallLetters,
    ForAll(
        Split(txtConfirmPassword.Text, ""),
        If(IsMatch(Value, "[a-z]"), Value)
    )
);

// Vérifie s’il y a des symboles spéciaux
ClearCollect(
    colCheckSymbol,
    ForAll(
        Split(txtConfirmPassword.Text, ""),
        If(IsMatch(Value, "[@,#,$,%,&,?,>,<,!]"), Value)
    )
);

// Détermine si le mot de passe est invalide
UpdateContext(
    {
        locPasswordError:
            CountRows(colCheckNumbers) = 0 ||
            CountRows(colCheckCapitalLetters) = 0 ||
            CountRows(colCheckSmallLetters) = 0 ||
            CountRows(colCheckSymbol) = 0
    }
);

// Si tout est correct, enregistre les données
If(
    !locPasswordError && !gblBlankEntry,
    Patch(
        LoginDemo,
        Defaults(LoginDemo),
        {
            Titre: txtFullName.Text,
            UserName: txtUsername.Text,
            EmailAddress: txtEmailAddress.Text,
            Password: txtConfirmPassword.Text
        }
    );
    UpdateContext({locPasswordError: false})
);

// Affiche les messages d’erreur ou de succès
If(
    locPasswordError,
    Notify(
        "Password must contain uppercase, lowercase, numbers, and special characters (@,#,$,%,&,?,>,<,!)",
        NotificationType.Error,
        3000
    );
    Set(gblShowErrorImage, true)
);

If(
    gblBlankEntry,
    Notify("All fields are required", NotificationType.Error, 3000);
    Set(gblShowErrorImage, true)
);

If(
    !locPasswordError && !gblBlankEntry,
    Notify("Registration Successful", NotificationType.Success, 3000)
);

// Réinitialise les champs si tout est correct
If(
    !locPasswordError && !gblBlankEntry,
    Reset(txtFullName);
    Reset(txtUsername);
    Reset(txtPassword);
    Reset(txtEmailAddress);
    Reset(txtConfirmPassword);
    Clear(colCheckCapitalLetters);
    Clear(colCheckNumbers);
    Clear(colCheckSmallLetters);
    Clear(colCheckSymbol)
);

